//! Compares `corvis::z` against real zod 4.4.3.
//!
//! `fixtures/zod4/parse.json` is generated by `fixtures/zod4/cases.mjs` with zod 4.4.3; each case
//! is rebuilt here by name and must give the same output (parsed data or issues, error helpers
//! and JSON Schema).

use std::collections::BTreeMap;

use corvis::z::{self, ZodSchema};
use serde_json::{Value, json};

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/zod4/parse.json")).unwrap()
}

fn s(x: impl Into<z::Schema>) -> z::Schema {
    x.into()
}

fn cat() -> z::Schema {
    s(z::object! { name: z::string(), children: z::array(z::lazy(cat)).optional() })
}

fn cat_required() -> z::Schema {
    s(z::object! { name: z::string(), children: z::array(z::lazy(cat_required)) })
}

fn linked_node() -> z::Schema {
    s(z::object! { v: z::number(), next: z::lazy(linked_node).optional() })
}

fn datetime_number_codec() -> z::ZCodec {
    z::codec(
        z::iso::datetime(),
        z::number(),
        |v, _| {
            let s = v.as_str().unwrap_or_default();
            let ms = chrono::DateTime::parse_from_rfc3339(s).map(|d| d.timestamp_millis()).unwrap_or_default();
            json!(ms)
        },
        |v, _| {
            let ms = v.as_i64().unwrap_or_default();
            let d = chrono::DateTime::from_timestamp_millis(ms).unwrap();
            json!(d.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string())
        },
    )
}

fn schema(name: &str) -> z::Schema {
    match name {
        // ----- primitives
        "string" => s(z::string()),
        "string.min" => s(z::string().min(3)),
        "string.min.msg" => s(z::string().min(3).message("muy corto")),
        "string.min.error" => s(z::string().min(3).error("corto")),
        "string.max" => s(z::string().max(2)),
        "string.length" => s(z::string().length(2)),
        "string.nonempty" => s(z::string().nonempty()),
        "string.min.max.email" => s(z::string().min(3).max(4).email()),
        "string.regex" => s(z::string().regex("^[A-Z]+$")),
        "string.regex.msg" => s(z::string().regex("^[A-Z]+$").message("solo mayus")),
        "string.regex.flags" => s(z::string().regex(("^a+$", "i"))),
        "string.startsWith" => s(z::string().starts_with("J")),
        "string.endsWith" => s(z::string().ends_with("z")),
        "string.includes" => s(z::string().includes("mid")),
        "string.includes.pos" => s(z::string().includes_at("a", 2)),
        "string.lowercase" => s(z::string().lowercase()),
        "string.uppercase" => s(z::string().uppercase()),
        "string.trim.min" => s(z::string().trim().min(1)),
        "string.toLowerCase.email" => s(z::string().to_lower_case().email()),
        "string.toUpperCase" => s(z::string().to_upper_case()),
        "string.normalize" => s(z::string().normalize("NFC")),
        "string.slugify" => s(z::string().slugify()),
        "string.email" => s(z::string().email()),
        "email" => s(z::email()),
        "email.min" => s(z::email().min(30)),
        "email.html5" => s(z::email_with(z::regexes::HTML5_EMAIL.clone())),
        "email.unicode" => s(z::email_with(z::regexes::UNICODE_EMAIL.clone())),
        "uuid" => s(z::uuid()),
        "uuidv4" => s(z::uuidv4()),
        "uuidv7" => s(z::uuidv7()),
        "string.uuid" => s(z::string().uuid()),
        "guid" => s(z::guid()),
        "url" => s(z::url()),
        "url.hostname" => s(z::url_with(z::UrlOptions { hostname: Some(r"^corvis\.dev$".into()), ..Default::default() })),
        "url.protocol" => s(z::url_with(z::UrlOptions { protocol: Some("^https$".into()), ..Default::default() })),
        "url.normalize" => s(z::url_with(z::UrlOptions { normalize: true, ..Default::default() })),
        "httpUrl" => s(z::http_url()),
        "string.url" => s(z::string().url()),
        "emoji" => s(z::emoji()),
        "nanoid" => s(z::nanoid()),
        "cuid" => s(z::cuid()),
        "cuid2" => s(z::cuid2()),
        "ulid" => s(z::ulid()),
        "xid" => s(z::xid()),
        "ksuid" => s(z::ksuid()),
        "ipv4" => s(z::ipv4()),
        "ipv6" => s(z::ipv6()),
        "cidrv4" => s(z::cidrv4()),
        "cidrv6" => s(z::cidrv6()),
        "mac" => s(z::mac(None)),
        "mac.dash" => s(z::mac(Some("-"))),
        "base64" => s(z::base64()),
        "base64url" => s(z::base64url()),
        "e164" => s(z::e164()),
        "jwt" => s(z::jwt(None)),
        "jwt.alg" => s(z::jwt(Some("HS512"))),
        "hostname" => s(z::hostname()),
        "hex" => s(z::hex()),
        "hash.sha256" => s(z::hash("sha256", None)),
        "hash.md5.base64" => s(z::hash("md5", Some("base64"))),
        "stringFormat" => s(z::string_format("cod", "^[A-Z]{3}$")),
        "stringFormat.fn" => s(z::string_format_fn("even-len", |v| v.encode_utf16().count() % 2 == 0)),
        "iso.datetime" => s(z::iso::datetime()),
        "iso.datetime.offset" => s(z::iso::datetime_with(z::IsoDatetime { offset: true, ..Default::default() })),
        "iso.datetime.local" => s(z::iso::datetime_with(z::IsoDatetime { local: true, ..Default::default() })),
        "iso.datetime.precision" => s(z::iso::datetime_with(z::IsoDatetime { precision: Some(3), ..Default::default() })),
        "iso.datetime.precision.minute" => s(z::iso::datetime_with(z::IsoDatetime { precision: Some(-1), ..Default::default() })),
        "iso.date" => s(z::iso::date()),
        "iso.time" => s(z::iso::time()),
        "iso.time.precision" => s(z::iso::time_with(0)),
        "iso.duration" => s(z::iso::duration()),
        "string.datetime" => s(z::string().datetime()),
        "string.date" => s(z::string().date()),
        "number" => s(z::number()),
        "number.min.max" => s(z::number().min(1.0).max(10.0)),
        "number.gt.lt" => s(z::number().gt(0.0).lt(5.0)),
        "number.positive" => s(z::number().positive()),
        "number.nonnegative" => s(z::number().nonnegative()),
        "number.negative" => s(z::number().negative()),
        "number.nonpositive" => s(z::number().nonpositive()),
        "number.multipleOf" => s(z::number().multiple_of(5.0)),
        "number.multipleOf.dec" => s(z::number().multiple_of(0.01)),
        "number.step" => s(z::number().step(0.5)),
        "number.int" => s(z::number().int()),
        "number.int.positive" => s(z::number().int().positive()),
        "number.safe" => s(z::number().safe()),
        "number.min.msg" => s(z::number().min(1.0).message("al menos 1")),
        "int" => s(z::int()),
        "int.min" => s(z::int().min(5.0)),
        "int32" => s(z::int32()),
        "uint32" => s(z::uint32()),
        "float32" => s(z::float32()),
        "float64" => s(z::float64()),
        "boolean" => s(z::boolean()),
        "null" => s(z::null()),
        "undefined" => s(z::undefined()),
        "void" => s(z::void()),
        "any" => s(z::any()),
        "unknown" => s(z::unknown()),
        "never" => s(z::never()),
        "literal" => s(z::literal("a")),
        "literal.number" => s(z::literal(3)),
        "literal.multi" => s(z::literal(json!(["a", 2, null]))),
        "literal.bool" => s(z::literal(true)),
        "enum" => s(z::enum_(["a", "b"])),
        "enum.msg" => s(z::enum_(["a", "b"]).message("opcion invalida")),
        "enum.extract" => s(z::enum_(["a", "b", "c"]).extract(&["a"])),
        "enum.exclude" => s(z::enum_(["a", "b", "c"]).exclude(&["a"])),
        "enum.object" => s(z::enum_entries([("A", json!("x")), ("B", json!("y"))])),
        "nativeEnum" => s(z::enum_entries([("Up", json!(1)), ("Down", json!("down"))])),
        "stringbool" => s(z::stringbool()),
        "stringbool.custom" => s(z::stringbool_with(z::StringBoolOptions {
            truthy: vec!["si".into()],
            falsy: vec!["no".into()],
            case_sensitive: true,
            ..Default::default()
        })),
        "templateLiteral" => {
            s(z::template_literal([z::TemplatePart::from("id-"), s(z::number()).into(), "-".into(), s(z::enum_(["a", "b"])).into()]))
        }
        "templateLiteral.str" => {
            s(z::template_literal([s(z::string().min(2)).into(), z::TemplatePart::from("@"), s(z::literal("x")).into()]))
        }
        "nan" => s(z::nan()),

        // ----- coerce
        "coerce.number" => s(z::coerce::number()),
        "coerce.number.int.min" => s(z::coerce::number().int().min(1.0)),
        "coerce.string" => s(z::coerce::string()),
        "coerce.boolean" => s(z::coerce::boolean()),
        "coerce.bigint" => s(z::coerce::bigint()),
        "coerce.date" => s(z::coerce::date()),
        "coerce.date.min.max" => s(z::coerce::date().min("2024-01-01").max("2024-12-31")),
        "coerce.bigint.min" => s(z::coerce::bigint().min(5).max(10)),
        "coerce.number.default" => z::coerce::number().int().min(1.0).max(100.0).default(20),

        // ----- objects
        "object" => s(z::object! { a: z::string(), b: z::number().optional() }),
        "object.strict" => s(z::object! { a: z::string() }.strict()),
        "strictObject" => s(z::strict_object! { a: z::string() }),
        "looseObject" => s(z::loose_object! { a: z::string() }),
        "object.passthrough" => s(z::object! { a: z::string() }.passthrough()),
        "object.catchall" => s(z::object! { a: z::string() }.catchall(z::number())),
        "object.optional.keys" => s(z::object! {
            a: z::string().optional(),
            b: z::undefined(),
            c: z::unknown(),
            d: z::any(),
            e: z::void(),
        }),
        "object.exactOptional" => s(z::object! { a: z::string().exact_optional() }),
        "object.default" => s(z::object! { a: z::string().default("d"), b: z::number().prefault(2) }),
        "object.default.a" => s(z::object! { a: z::string().default("d") }),
        "object.default.order" => s(z::object! { x: z::string(), a: z::string().default("d"), b: z::string().optional() }),
        "object.index.keys" => s(z::object! { b: z::string(), "10": z::string(), "2": z::string() }),
        "record.index.keys" => s(z::record_with(z::string(), z::number())),
        "object.nested" => s(z::object! { items: z::array(z::object! { q: z::number().gt(0.0) }) }),
        "object.extend" => s(z::object! { a: z::string() }.extend(z::object! { b: z::number() })),
        "object.safeExtend" => s(z::object! { a: z::string() }.safe_extend(z::object! { a: z::string().min(2) })),
        "object.merge" => s(z::object! { a: z::string() }.merge(z::object! { b: z::number() })),
        "object.pick.strict" => s(z::object! { a: z::string(), b: z::number() }.strict().pick(&["a"])),
        "object.omit" => s(z::object! { a: z::string(), b: z::number() }.omit(&["b"])),
        "object.partial" => s(z::object! { a: z::string(), b: z::number() }.partial()),
        "object.partial.keys" => s(z::object! { a: z::string(), b: z::number() }.partial_fields(&["a"])),
        "object.required" => s(z::object! { a: z::string().optional(), b: z::number().optional() }.required()),
        "object.required.keys" => s(z::object! { a: z::string().optional(), b: z::number().optional() }.required_fields(&["a"])),
        "object.keyof" => s(z::object! { a: z::string(), b: z::number() }.keyof()),
        "object.refine" => z::object! { a: z::number(), b: z::number() }
            .refine(|v| v["a"].as_f64() <= v["b"].as_f64(), z::params().message("a<=b").path(["b"])),
        "object.refine.skip" => z::object! { a: z::number(), b: z::number() }.refine(|_| false, z::params().message("never")),
        "object.refine.when" => {
            z::object! { a: z::number(), b: z::number() }.refine(|_| false, z::params().message("always").when(|_| true))
        }
        "object.superRefine" => z::object! { a: z::string() }.super_refine(|v, ctx| {
            ctx.add(z::issue().code(z::ZodIssueCode::Custom).message("x").path(["q"]));
            ctx.add_issue("s");
            ctx.add(
                z::issue()
                    .code(z::ZodIssueCode::TooSmall)
                    .param("origin", "string")
                    .param("minimum", 3)
                    .param("inclusive", true)
                    .param("input", v["a"].clone())
                    .path(["a"]),
            );
        }),
        "object.check" => z::object! { a: z::string() }.check_fn(|p| {
            if p.value.json().is_some_and(|v| v["a"] == "x") {
                let input = p.value.clone();
                p.push(z::RawIssue::new(
                    vec![("code", json!("custom")), ("message", json!("no x")), ("path", json!(["a"]))],
                    input,
                    None,
                    None,
                ));
            }
        }),

        // ----- arrays / tuples / records
        "array" => s(z::array(z::string())),
        "array.min.max" => s(z::array(z::string()).min(1).max(2)),
        "array.length" => s(z::array(z::number()).length(2)),
        "array.nonempty" => s(z::array(z::number()).nonempty()),
        "array.method" => s(z::string().array().max(1)),
        "tuple" => s(z::tuple([s(z::string()), s(z::number())])),
        "tuple.rest" => s(z::tuple([s(z::string())]).rest(z::number())),
        "tuple.optional" => s(z::tuple([s(z::string()), z::number().optional()])),
        "record" => s(z::record_with(z::string(), z::number())),
        "record.keymin" => s(z::record_with(z::string().min(2), z::number())),
        "record.enum" => s(z::record_with(z::enum_(["a", "b"]), z::number())),
        "record.nested" => s(z::record_with(z::enum_(["x"]), z::record_with(z::string(), z::string()))),
        "partialRecord" => s(z::partial_record(z::enum_(["a", "b"]), z::number())),
        "looseRecord" => s(z::loose_record(z::string().regex("^a"), z::number())),
        "record.number.key" => s(z::record_with(z::number(), z::string())),
        "record.literal.key" => s(z::record_with(z::literal(json!(["a", "b"])), z::string())),

        // ----- unions
        "union" => z::union([s(z::string()), s(z::number())]),
        "union.dirty" => z::union([s(z::string().max(3)), s(z::number())]),
        "union.objects" => z::union([s(z::object! { a: z::string() }), s(z::object! { b: z::number() })]),
        "or" => z::string().or(z::number()),
        "xor" => z::xor([s(z::string()), s(z::string().min(2))]),
        "discriminatedUnion" => z::discriminated_union(
            "type",
            [s(z::object! { "type": z::literal("a"), a: z::string() }), s(z::object! { "type": z::literal("b"), b: z::number() })],
        ),
        "discriminatedUnion.enum" => {
            z::discriminated_union("k", [s(z::object! { k: z::enum_(["x", "y"]) }), s(z::object! { k: z::literal(3) })])
        }
        "intersection" => z::intersection(z::object! { a: z::string() }, z::object! { b: z::number() }),
        "intersection.conflict" => z::intersection(z::string().transform(|_| json!(1)), z::string().transform(|_| json!(2))),
        "and" => z::object! { a: z::string() }.and(z::object! { a: z::string().min(2) }),

        "union.literals" => z::union([s(z::literal("a")), s(z::literal("b"))]),
        "union.nested.du" => s(z::object! {
            shape: z::discriminated_union("kind", [
                s(z::object! { kind: z::literal("circle"), r: z::number().positive() }),
                s(z::object! { kind: z::literal("square"), side: z::number() }),
            ]),
        }),
        "object.catch.field" => s(z::object! { a: z::number().catch(-1), b: z::string() }),
        "array.objects.strict" => s(z::array(z::strict_object! { id: z::uuid() }).min(1)),

        // ----- wrappers
        "optional" => z::string().optional(),
        "nullable" => z::string().nullable(),
        "nullish" => z::string().nullish(),
        "default" => z::string().min(5).default("ab"),
        "default.fn" => z::array(z::string()).default_fn(|| json!([])),
        "prefault" => z::string().min(5).prefault("ab"),
        "catch" => z::number().catch(0),
        "catch.fn" => z::number().catch_fn(|ctx| json!(ctx.error.issues.len())),
        "nonoptional" => z::string().optional().nonoptional(),
        "nonoptional.msg" => s(z::ZNonOptional::new(z::string().optional()).error("requerido")),
        "readonly" => z::object! { a: z::string() }.readonly(),
        "success" => z::success(z::string()),
        "brand" => z::string().brand(),
        "transform" => z::string().transform(|v| json!(v.as_str().unwrap().encode_utf16().count())),
        "transform.issue" => z::string().try_transform(|v, ctx| {
            if v == "x" {
                ctx.add(z::issue().code(z::ZodIssueCode::Custom).message("no x"));
                return None;
            }
            Some(json!(format!("{}!", v.as_str().unwrap())))
        }),
        "pipe" => z::string().transform(|v| json!(v.as_str().unwrap().len())).pipe(z::number().min(5.0)),
        "preprocess" => z::preprocess(
            |v| match v {
                Some(Value::String(s)) => Some(json!(s.split(',').collect::<Vec<_>>())),
                other => other.cloned(),
            },
            z::array(z::string()),
        ),
        "refine" => z::string().refine(|v| v.as_str().unwrap().len() > 2, ()),
        "refine.msg" => z::string().refine(|v| v.as_str().unwrap().len() > 2, "muy corto"),
        "refine.abort" => z::string().refine(|v| v.as_str().unwrap().len() > 2, z::params().message("r1").abort()).refine(|_| false, "r2"),
        "min.then.refine" => z::string().min(3).refine(|_| false, ()),
        "refine.params" => z::string().refine(|_| false, z::params().params(json!({ "foo": 1 }))),
        "superRefine.fatal" => z::string()
            .super_refine(|_, ctx| ctx.add(z::issue().code(z::ZodIssueCode::Custom).message("f").fatal()))
            .refine(|_| false, "after"),
        "overwrite" => z::number().max(5.0).overwrite(|v| json!(v.as_f64().unwrap() * 2.0)),
        "codec" => s(datetime_number_codec()),
        "codec.encode" => s(datetime_number_codec()),
        "stringbool.encode" => s(z::stringbool()),
        "invertCodec" => s(z::invert_codec(&datetime_number_codec())),
        "email.idn" => s(z::email_with(z::regexes::IDN_EMAIL.clone())),
        "lazy" => cat(),
        "json" => z::json(),
        "custom" => z::custom(|v| v.as_str().is_some_and(|s| s.starts_with('a')), ()),
        "custom.msg" => z::custom(|v| v == &json!(1), "debe ser 1"),

        // ----- locales
        "es.string" => s(z::string()),
        "es.sizes" => s(z::object! {
            s: z::string().min(3).max(4),
            a: z::array(z::number()).min(1),
            n: z::number().gt(1.0).lte(2.0),
            i: z::int(),
        }),
        "es.formats" => s(z::object! {
            e: z::email(), u: z::uuid(), d: z::iso::datetime(), r: z::string().regex("^a$"), sw: z::string().starts_with("x"),
            ew: z::string().ends_with("y"), inc: z::string().includes("z"), mac: z::mac(None), ip: z::ipv4(),
        }),
        "es.values" => s(z::object! { e: z::enum_(["a", "b"]), l: z::literal("x"), m: z::number().multiple_of(3.0) }.strict()),
        "es.misc" => s(z::object! {
            u: z::union([s(z::string()), s(z::number())]),
            r: z::record_with(z::string().min(2), z::string()),
            d: z::discriminated_union("t", [s(z::object! { t: z::literal("a") })]),
        }),

        // ----- errors
        "error.param.fn" => s(z::string()
            .error(z::error_fn(|iss| Some(if iss.input_is_undefined() { "requerido".to_string() } else { "no es string".to_string() })))),
        "error.param.str" => s(z::string().error("debe ser texto")),
        "error.min.fn" => s(z::string().min(3).error(z::error_fn(|iss| Some(format!("min {}", iss.get("minimum").unwrap()))))),
        "error.object.fn" => s(z::object! { a: z::string() }.error(z::error_fn(|_| Some("obj".to_string())))),
        "error.reportInput" => s(z::object! { a: z::string().min(2) }),
        "error.parse.error" => s(z::object! { a: z::string().min(2), b: z::number() }),
        "error.format" => z::object! {
            a: z::string(),
            b: z::object! { c: z::number() },
            d: z::array(z::string()),
        }
        .refine(|_| false, "raiz"),
        other => panic!("no Rust schema for fixture case `{other}`"),
    }
}

fn json_schema_of(name: &str) -> z::Schema {
    match name {
        "string" => s(z::string()),
        "string.checks" => s(z::string().min(1).max(5).regex("^a").starts_with("a")),
        "email" => s(z::email()),
        "email.regex" => s(z::email().regex("a")),
        "uuid" => s(z::uuid()),
        "url" => s(z::url()),
        "iso.datetime" => s(z::iso::datetime()),
        "iso.date" => s(z::iso::date()),
        "iso.time" => s(z::iso::time()),
        "iso.duration" => s(z::iso::duration()),
        "ipv4" => s(z::ipv4()),
        "base64" => s(z::base64()),
        "number" => s(z::number().min(5.0).max(10.0)),
        "number.int.min" => s(z::number().min(5.0).int()),
        "int" => s(z::int()),
        "int.min" => s(z::int().min(5.0)),
        "int32" => s(z::int32()),
        "number.exclusive" => s(z::number().gt(0.0).lt(5.0).multiple_of(0.5)),
        "boolean" => s(z::boolean()),
        "null" => s(z::null()),
        "literal" => s(z::literal("a")),
        "literal.multi" => s(z::literal(json!(["a", 1]))),
        "enum" => s(z::enum_(["a", "b"])),
        "object" => s(z::object! {
            a: z::string(),
            b: z::number().optional(),
            c: z::string().default("x"),
            d: z::string().nullable(),
        }),
        "object.io.input" => s(z::object! { c: z::string().default("x") }),
        "object.strict" => s(z::strict_object! { a: z::string() }),
        "object.loose" => s(z::loose_object! { a: z::string() }),
        "object.catchall" => s(z::object! { a: z::string() }.catchall(z::number())),
        "array" => s(z::array(z::string()).min(1).max(3)),
        "tuple" => s(z::tuple([s(z::string()), s(z::number())]).rest(z::boolean())),
        "record" => s(z::record_with(z::string(), z::number())),
        "record.enum" => s(z::record_with(z::enum_(["a", "b"]), z::number())),
        "partialRecord" => s(z::partial_record(z::enum_(["a", "b"]), z::string())),
        "looseRecord" => s(z::loose_record(z::string().regex("^a"), z::string())),
        "union" => z::union([s(z::string()), s(z::number())]),
        "discriminatedUnion" => z::discriminated_union("t", [s(z::object! { t: z::literal("a") }), s(z::object! { t: z::literal("b") })]),
        "intersection" => z::intersection(z::object! { a: z::string() }, z::object! { b: z::number() }),
        "nullable" => z::string().nullable(),
        "nullable.object" => z::object! { a: z::string() }.nullable(),
        "describe" => z::string().describe("Un texto"),
        "meta" => {
            z::object! { a: z::string().meta(json!({ "title": "A", "examples": ["x"] })) }.meta(json!({ "id": "Obj", "description": "d" }))
        }
        "default" => z::string().default("x"),
        "templateLiteral" => s(z::template_literal([z::TemplatePart::from("id-"), s(z::number()).into()])),
        "stringbool" => s(z::stringbool()),
        "pipe.output" | "pipe.input" => z::string().transform(|v| json!(v.as_str().unwrap().len())).pipe(z::number()),
        "lazy" => z::lazy(cat_required),
        "target.draft-07" => s(z::object! { a: z::string().nullable(), t: z::tuple([s(z::string())]) }),
        "target.openapi-3.0" => s(z::object! { a: z::string().nullable(), l: z::literal("x") }),
        "readonly" => z::object! { a: z::string() }.readonly(),
        "any" => s(z::any()),
        "unknown" => s(z::unknown()),
        "never" => s(z::never()),
        "json" => z::json(),
        "reused.inline" | "reused.ref" => {
            let name = s(z::string().min(3));
            s(z::object! { a: name.clone(), b: name })
        }
        "cycles.throw" => z::lazy(cat_required),
        "lazy.nested" => s(z::object! { head: z::lazy(linked_node) }),
        "unrep.bigint" => s(z::bigint()),
        "unrep.bigint.any" => s(z::object! { a: z::bigint(), b: z::string() }),
        "unrep.date" => s(z::date()),
        "unrep.transform" | "unrep.transform.any" => z::string().transform(|v| json!(v.as_str().unwrap().len())),
        "io.input.object" | "io.output.object" => s(z::object! {
            a: z::string().default("x"),
            b: z::string().optional(),
            c: z::string().prefault("y"),
            d: z::number().catch(0),
        }),
        "meta.id.nested" => s(z::object! {
            name: z::string().meta(json!({ "id": "PersonName", "description": "nombre" })),
            tags: z::array(z::string()),
        }),
        "meta.fields" => z::string().meta(json!({ "title": "T", "description": "D", "examples": ["a"], "deprecated": true, "x-extra": 1 })),
        "describe.nested" => s(z::object! { a: z::string().describe("campo a").optional() }),
        "formats" => s(z::object! {
            cuid: z::cuid(), cuid2: z::cuid2(), ulid: z::ulid(), ipv6: z::ipv6(), cidrv4: z::cidrv4(), e164: z::e164(), jwt: z::jwt(None),
            hostname: z::hostname(), emoji: z::emoji(), nanoid: z::nanoid(), base64url: z::base64url(), guid: z::guid(), uuidv4: z::uuidv4(),
            hex: z::hex(), mac: z::mac(None), httpUrl: z::http_url(), lower: z::string().lowercase(), upper: z::string().uppercase(),
            incl: z::string().includes("x"), ends: z::string().ends_with("z"), len: z::string().length(3),
        }),
        "enum.native" => s(z::enum_entries([("A", json!(1)), ("B", json!("b"))])),
        "literal.null" => s(z::literal(Value::Null)),
        "literal.mixed" => s(z::literal(json!(["a", 1, true, null]))),
        "tuple.draft07" => s(z::tuple([s(z::string()), s(z::number())]).rest(z::boolean())),
        "tuple.openapi" => s(z::tuple([s(z::string()), s(z::number())])),
        "draft-04" => s(z::object! { a: z::number().gt(1.0).lt(5.0), b: z::literal("x"), c: z::string().nullable() }),
        "default.fn" => z::array(z::string()).default_fn(|| json!(["a"])),
        "catch" => z::number().catch(0),
        "readonly.array" => z::array(z::string()).readonly(),
        "union.nullable" => z::union([s(z::string()), s(z::number())]).nullable(),
        "object.partial" => s(z::object! { a: z::string(), b: z::number() }.partial()),
        "object.required" => s(z::object! { a: z::string().optional(), b: z::number().optional() }.required()),
        "stringbool.output" => s(z::stringbool()),
        "codec.input" | "codec.output" => s(datetime_number_codec()),
        "preprocess" => z::preprocess(|v| v.cloned(), z::number()),
        "nullable.openapi.object" => z::object! { a: z::string() }.nullable(),
        "number.openapi.exclusive" => s(z::number().gt(0.0).lt(5.0)),
        "int.positive" => s(z::int().positive()),
        "array.length" => s(z::array(z::number()).length(2)),
        "record.draft07" | "record.openapi" => s(z::record_with(z::string().min(1), z::number())),
        "intersection.objects" => z::object! { a: z::string() }.and(z::object! { b: z::number() }.strict()),
        "success" => z::success(z::string()),
        "nan.any" => s(z::nan()),
        "void.any" => s(z::object! { a: z::void(), b: z::undefined() }),
        "custom.any" => z::custom(|_| true, ()),
        other => panic!("no Rust schema for JSON Schema fixture `{other}`"),
    }
}

/// Order-sensitive JSON equality (key order is part of zod's output). Numbers compare as
/// JavaScript numbers (`4` == `4.0`, last-digit float parsing differences tolerated) and the
/// fixture encodes `BigInt`s as `"12n"`.
fn same(got: &Value, want: &Value) -> bool {
    match (got, want) {
        (Value::Number(a), Value::Number(b)) => {
            let (a, b) = (a.as_f64().unwrap(), b.as_f64().unwrap());
            a == b || ((a - b) / b).abs() < 1e-15
        }
        (Value::Number(a), Value::String(b)) if b.ends_with('n') => b[..b.len() - 1].parse::<f64>().ok() == a.as_f64(),
        (Value::Array(a), Value::Array(b)) => a.len() == b.len() && a.iter().zip(b).all(|(a, b)| same(a, b)),
        (Value::Object(a), Value::Object(b)) => a.len() == b.len() && a.iter().zip(b).all(|((ka, va), (kb, vb))| ka == kb && same(va, vb)),
        (a, b) => a == b,
    }
}

fn decode_input(v: &Value) -> Option<Value> {
    if v.get("$undefined").is_some() { None } else { Some(v.clone()) }
}

#[test]
fn zod4_parse_fixtures() {
    run_parse_fixtures("cases", z::ZodVersion::V4);
}

/// zod 3 mode, checked against the `zod/v3` build shipped with zod 4.4.3.
#[test]
fn zod3_parse_fixtures() {
    run_parse_fixtures("casesV3", z::ZodVersion::V3);
}

fn run_parse_fixtures(list: &str, version: z::ZodVersion) {
    let fx = fixture();
    assert_eq!(fx["zod"], "4.4.3");
    let mut failures: BTreeMap<String, Vec<String>> = BTreeMap::new();
    z::with_version(version, || {
        for case in fx[list].as_array().unwrap() {
            let name = case["name"].as_str().unwrap();
            let schema = schema(name);
            let mode = case["mode"].as_str().unwrap();
            let mut opts = z::ParseOptions::new().report_input(case["reportInput"].as_bool().unwrap());
            if case["globalError"].as_bool().unwrap() {
                opts = opts.error(z::error_fn(|iss| Some(format!("global {}", iss.code.as_str()))));
            }
            match case["locale"].as_str() {
                Some("es") => opts = opts.error(z::locales::es()),
                Some(other) => panic!("locale {other}"),
                None => {}
            }
            if mode == "encode" {
                opts = opts.direction(z::Direction::Backward);
            }
            for expected in case["results"].as_array().unwrap() {
                let input = decode_input(&expected["input"]);
                let label = format!("{} <- {}", name, expected["input"]);
                if let Some(msg) = expected.get("throws") {
                    let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| schema.parse_opt(input.as_ref(), &opts)));
                    if r.is_ok() {
                        failures.entry(label).or_default().push(format!("expected a panic: {msg}"));
                    }
                    continue;
                }
                let got = schema.parse_opt(input.as_ref(), &opts);
                let mut diffs = Vec::new();
                match (expected["success"].as_bool().unwrap(), got) {
                    (true, Ok(v)) => {
                        let want = if expected.get("undefined").is_some() { Value::Null } else { expected["data"].clone() };
                        if !same(&v, &want) {
                            diffs.push(format!("data: got {v}, want {want}"));
                        }
                    }
                    (true, Err(e)) => diffs.push(format!("unexpected failure: {}", e.to_json())),
                    (false, Ok(v)) => diffs.push(format!("unexpected success: {v}; want {}", expected["issues"])),
                    (false, Err(e)) => {
                        let got = e.to_json();
                        if !same(&got, &expected["issues"]) {
                            diffs.push(format!("issues:\n   got  {got}\n   want {}", expected["issues"]));
                        }
                        if expected.get("flatten").is_some() {
                            for (key, got) in [
                                ("flatten", z::flatten_error(&e)),
                                ("treeify", z::treeify_error(&e)),
                                ("format", z::format_error(&e)),
                                ("prettify", json!(z::prettify_error(&e))),
                                ("message", json!(e.message())),
                            ] {
                                if expected.get(key).is_none() {
                                    continue;
                                }
                                if !same(&got, &expected[key]) {
                                    diffs.push(format!("{key}:\n   got  {got}\n   want {}", expected[key]));
                                }
                            }
                        }
                    }
                }
                if !diffs.is_empty() {
                    failures.entry(label).or_default().extend(diffs);
                }
            }
        }
    });
    let report: Vec<String> = failures.iter().map(|(k, v)| format!("* {k}\n  {}", v.join("\n  "))).collect();
    assert!(failures.is_empty(), "{} fixture mismatches:\n{}", failures.len(), report.join("\n"));
}

#[test]
fn zod4_json_schema_fixtures() {
    let fx = fixture();
    let mut failures = Vec::new();
    for case in fx["jsonSchemas"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let schema = json_schema_of(name);
        let mut opts = z::JsonSchemaOptions::default();
        if let Some(p) = case["params"].as_object() {
            for (k, v) in p {
                let v = v.as_str().unwrap().to_string();
                match k.as_str() {
                    "target" => opts.target = v,
                    "io" => opts.io = v,
                    "unrepresentable" => opts.unrepresentable = v,
                    "cycles" => opts.cycles = v,
                    "reused" => opts.reused = v,
                    _ => panic!("unknown param {k}"),
                }
            }
        }
        let got = z::to_json_schema(&schema, &opts);
        match (case.get("schema"), got) {
            (Some(want), Ok(got)) if same(&got, want) => {}
            (Some(want), got) => failures.push(format!("* {name}\n   got  {got:?}\n   want {want}")),
            (None, Err(e)) if json!(e) == case["error"] => {}
            (None, Err(e)) => failures.push(format!("* {name}: error {e:?}, want {}", case["error"])),
            (None, Ok(got)) => failures.push(format!("* {name}: expected error {}, got {got}", case["error"])),
        }
    }
    assert!(failures.is_empty(), "{} JSON Schema mismatches:\n{}", failures.len(), failures.join("\n"));
}
